import { FC, ChangeEvent } from 'react';
import { ParticleConfig, PRESET_THEMES, InteractionMode } from '../types';
import { Sliders, X, Sparkles, RefreshCw, Zap } from 'lucide-react';

interface ControlsProps {
  config: ParticleConfig;
  onChangeConfig: (newConfig: Partial<ParticleConfig>) => void;
  onApplyPreset: (presetId: string) => void;
  onBurst: () => void;
  onReset: () => void;
  onClose: () => void;
}

const Controls: FC<ControlsProps> = ({
  config,
  onChangeConfig,
  onApplyPreset,
  onBurst,
  onReset,
  onClose,
}) => {
  const handleCountChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ count: Number(e.target.value) });
  };

  const handleSpeedChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ speed: Number(e.target.value) });
  };

  const handleRadiusChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ connectionRadius: Number(e.target.value) });
  };

  const handleSizeChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ particleSize: Number(e.target.value) });
  };

  const handleModeChange = (mode: InteractionMode) => {
    onChangeConfig({ interactionMode: mode });
  };

  const handleToggleConnections = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ showConnections: e.target.checked });
  };

  const handleToggleAutoMove = (e: ChangeEvent<HTMLInputElement>) => {
    onChangeConfig({ autoMove: e.target.checked });
  };

  return (
    <div className="ui-panel">
      <div className="panel-header">
        <div className="panel-title">
          <Sliders size={18} />
          <span>パーティクル設定</span>
        </div>
        <button
          type="button"
          className="panel-close-btn"
          onClick={onClose}
          aria-label="パネルを閉じる"
        >
          <X size={18} />
        </button>
      </div>

      <div className="panel-body">
        {/* プリセット選択 */}
        <div className="control-group">
          <div className="control-label">
            <span>テーマプリセット</span>
          </div>
          <div className="preset-grid">
            {PRESET_THEMES.map((preset) => {
              const isActive = config.colorMode === preset.config.colorMode;
              return (
                <button
                  key={preset.id}
                  type="button"
                  className={isActive ? 'preset-btn preset-btn-active' : 'preset-btn'}
                  onClick={() => onApplyPreset(preset.id)}
                >
                  {preset.name}
                </button>
              );
            })}
          </div>
        </div>

        {/* インタラクションモード */}
        <div className="control-group">
          <div className="control-label">
            <span>反応モード</span>
          </div>
          <div className="mode-toggle-group">
            <button
              type="button"
              className={config.interactionMode === 'attract' ? 'mode-btn mode-btn-active' : 'mode-btn'}
              onClick={() => handleModeChange('attract')}
            >
              引き寄せ
            </button>
            <button
              type="button"
              className={config.interactionMode === 'repel' ? 'mode-btn mode-btn-active' : 'mode-btn'}
              onClick={() => handleModeChange('repel')}
            >
              反発
            </button>
            <button
              type="button"
              className={config.interactionMode === 'vortex' ? 'mode-btn mode-btn-active' : 'mode-btn'}
              onClick={() => handleModeChange('vortex')}
            >
              渦潮
            </button>
          </div>
        </div>

        {/* パーティクル数 */}
        <div className="control-group">
          <div className="control-label">
            <span>粒子数</span>
            <span className="control-value">{config.count}</span>
          </div>
          <input
            type="range"
            min={50}
            max={400}
            step={10}
            value={config.count}
            onChange={handleCountChange}
            className="slider"
          />
        </div>

        {/* 速度 */}
        <div className="control-group">
          <div className="control-label">
            <span>運動速度</span>
            <span className="control-value">{config.speed.toFixed(1)}x</span>
          </div>
          <input
            type="range"
            min={0.2}
            max={3.5}
            step={0.1}
            value={config.speed}
            onChange={handleSpeedChange}
            className="slider"
          />
        </div>

        {/* 粒子サイズ */}
        <div className="control-group">
          <div className="control-label">
            <span>粒子の大きさ</span>
            <span className="control-value">{config.particleSize.toFixed(1)}px</span>
          </div>
          <input
            type="range"
            min={1.0}
            max={6.0}
            step={0.2}
            value={config.particleSize}
            onChange={handleSizeChange}
            className="slider"
          />
        </div>

        {/* 結合ラインの距離 */}
        <div className="control-group">
          <div className="control-label">
            <span>結合線の感知距離</span>
            <span className="control-value">{config.connectionRadius}px</span>
          </div>
          <input
            type="range"
            min={40}
            max={180}
            step={5}
            value={config.connectionRadius}
            onChange={handleRadiusChange}
            className="slider"
          />
        </div>

        {/* トグルスイッチ群 */}
        <label className="toggle-switch">
          <span className="toggle-label">光の結合線を描画</span>
          <input
            type="checkbox"
            checked={config.showConnections}
            onChange={handleToggleConnections}
          />
        </label>

        <label className="toggle-switch">
          <span className="toggle-label">自動巡航モード (Demo)</span>
          <input
            type="checkbox"
            checked={config.autoMove}
            onChange={handleToggleAutoMove}
          />
        </label>

        {/* アクションボタン */}
        <div className="action-btn-group">
          <button
            type="button"
            className="action-btn action-btn-primary"
            onClick={onBurst}
          >
            <Sparkles size={14} />
            <span>光のバースト</span>
          </button>
          <button
            type="button"
            className="action-btn action-btn-danger"
            onClick={onReset}
          >
            <RefreshCw size={14} />
            <span>リセット</span>
          </button>
        </div>
      </div>

      <div className="panel-footer">
        画面をクリック/ドラッグすると粒子が反応します
      </div>
    </div>
  );
};

export default Controls;

import { FC, useState, useEffect, useRef, useCallback, PointerEvent as ReactPointerEvent } from 'react';
import { ParticleConfig, ParticleItem, PRESET_THEMES, ColorMode } from './types';
import Controls from './components/Controls';
import { Sliders, Activity } from 'lucide-react';

interface BurstParticle extends ParticleItem {
  alpha: number;
}

const App: FC = () => {
  const [config, setConfig] = useState<ParticleConfig>(PRESET_THEMES[0].config);
  const [isPanelOpen, setIsPanelOpen] = useState<boolean>(true);
  const [showToast, setShowToast] = useState<boolean>(true);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const particlesRef = useRef<ParticleItem[]>([]);
  const burstsRef = useRef<BurstParticle[]>([]);
  const pointerRef = useRef<{ x: number; y: number; active: boolean; isUser: boolean }>({
    x: 0,
    y: 0,
    active: false,
    isUser: false,
  });
  const autoAngleRef = useRef<number>(0);
  const animFrameIdRef = useRef<number | null>(null);

  // 初回ガイドトーストのフェードアウトタイマー
  useEffect(() => {
    const timer = setTimeout(() => {
      setShowToast(false);
    }, 4500);
    return () => clearTimeout(timer);
  }, []);

  // カラーモードに応じた色相ジェネレータ
  const getParticleHue = useCallback((mode: ColorMode): number => {
    switch (mode) {
      case 'neon':
        // シアン (180) 〜 マゼンタ (320)
        return Math.random() > 0.5 ? 180 + Math.random() * 40 : 290 + Math.random() * 40;
      case 'aurora':
        // エメラルドグリーン (140) 〜 シアン (190)
        return 140 + Math.random() * 60;
      case 'cyber':
        // 電脳イエロー (50) 〜 シアン (180)
        return Math.random() > 0.6 ? 55 + Math.random() * 20 : 185 + Math.random() * 20;
      case 'fire':
        // 朱色〜深紅 (0〜35)
        return 5 + Math.random() * 35;
      case 'magic':
        // バイオレット〜ピンク (260〜320)
        return 260 + Math.random() * 60;
      default:
        return Math.random() * 360;
    }
  }, []);

  // パーティクル初期化
  const initParticles = useCallback((count: number, width: number, height: number, mode: ColorMode) => {
    const newParticles: ParticleItem[] = [];
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = (0.4 + Math.random() * 1.2);
      newParticles.push({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        baseRadius: 1 + Math.random() * 2,
        radius: 1 + Math.random() * 2,
        hue: getParticleHue(mode),
        life: 0,
        maxLife: 200 + Math.random() * 300,
      });
    }
    particlesRef.current = newParticles;
  }, [getParticleHue]);

  // 設定更新ハンドラ
  const handleConfigChange = (newValues: Partial<ParticleConfig>) => {
    setConfig((prev) => {
      const updated = { ...prev, ...newValues };
      if (newValues.count !== undefined || newValues.colorMode !== undefined) {
        if (canvasRef.current) {
          initParticles(
            updated.count,
            canvasRef.current.width,
            canvasRef.current.height,
            updated.colorMode
          );
        }
      }
      return updated;
    });
  };

  // プリセット適用
  const handleApplyPreset = (presetId: string) => {
    const preset = PRESET_THEMES.find((p) => p.id === presetId);
    if (preset) {
      setConfig({ ...preset.config });
      if (canvasRef.current) {
        initParticles(
          preset.config.count,
          canvasRef.current.width,
          canvasRef.current.height,
          preset.config.colorMode
        );
      }
    }
  };

  // バースト生成
  const triggerBurst = useCallback((burstX?: number, burstY?: number) => {
    if (!canvasRef.current) return;
    const cx = burstX ?? (pointerRef.current.active ? pointerRef.current.x : canvasRef.current.width / 2);
    const cy = burstY ?? (pointerRef.current.active ? pointerRef.current.y : canvasRef.current.height / 2);

    const burstCount = 45;
    for (let i = 0; i < burstCount; i++) {
      const angle = (Math.PI * 2 * i) / burstCount + (Math.random() - 0.5) * 0.2;
      const force = 3.5 + Math.random() * 6.5;
      burstsRef.current.push({
        x: cx,
        y: cy,
        vx: Math.cos(angle) * force,
        vy: Math.sin(angle) * force,
        baseRadius: 2 + Math.random() * 3,
        radius: 2 + Math.random() * 3,
        hue: getParticleHue(config.colorMode),
        life: 0,
        maxLife: 40 + Math.random() * 30,
        alpha: 1.0,
      });
    }
  }, [config.colorMode, getParticleHue]);

  // リセット
  const handleReset = () => {
    const defaultPreset = PRESET_THEMES[0];
    setConfig(defaultPreset.config);
    if (canvasRef.current) {
      initParticles(
        defaultPreset.config.count,
        canvasRef.current.width,
        canvasRef.current.height,
        defaultPreset.config.colorMode
      );
    }
    burstsRef.current = [];
  };

  // ポインタイベント
  const handlePointerDown = (e: ReactPointerEvent<HTMLCanvasElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    pointerRef.current = { x, y, active: true, isUser: true };
    triggerBurst(x, y);
  };

  const handlePointerMove = (e: ReactPointerEvent<HTMLCanvasElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    pointerRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      active: true,
      isUser: true,
    };
  };

  const handlePointerUp = () => {
    pointerRef.current.isUser = false;
  };

  const handlePointerLeave = () => {
    pointerRef.current.isUser = false;
    pointerRef.current.active = false;
  };

  // リサイズハンドラ
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.scale(dpr, dpr);
      }

      // 初回またはリサイズ時にパーティクル再生成
      if (particlesRef.current.length === 0) {
        initParticles(config.count, width, height, config.colorMode);
      }
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [config.count, config.colorMode, initParticles]);

  // メインアニメーション描画ループ
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let isRunning = true;

    const render = () => {
      if (!isRunning) return;

      const width = window.innerWidth;
      const height = window.innerHeight;

      // 自動巡航の更新（ユーザーが触れていない場合）
      if (config.autoMove && !pointerRef.current.isUser) {
        autoAngleRef.current += 0.018 * config.speed;
        const radiusX = Math.min(width, height) * 0.32;
        const radiusY = Math.min(width, height) * 0.22;
        pointerRef.current.x = width / 2 + Math.cos(autoAngleRef.current) * radiusX;
        pointerRef.current.y = height / 2 + Math.sin(autoAngleRef.current * 1.5) * radiusY;
        pointerRef.current.active = true;
      }

      // 背景のフェード消去（軌跡効果）
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = 'rgba(10, 11, 16, 0.25)';
      ctx.fillRect(0, 0, width, height);

      // パーティクル結合ライン描画
      if (config.showConnections) {
        ctx.globalCompositeOperation = 'lighter';
        const pLen = particlesRef.current.length;
        const maxDist = config.connectionRadius;

        for (let i = 0; i < pLen; i++) {
          const p1 = particlesRef.current[i];
          for (let j = i + 1; j < pLen; j++) {
            const p2 = particlesRef.current[j];
            const dx = p1.x - p2.x;
            const dy = p1.y - p2.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < maxDist) {
              const alpha = (1 - dist / maxDist) * 0.45;
              ctx.strokeStyle = `hsla(${p1.hue}, 90%, 65%, ${alpha})`;
              ctx.lineWidth = (1 - dist / maxDist) * 1.5;
              ctx.beginPath();
              ctx.moveTo(p1.x, p1.y);
              ctx.lineTo(p2.x, p2.y);
              ctx.stroke();
            }
          }
        }
      }

      // 通常パーティクルの更新と描画
      ctx.globalCompositeOperation = 'screen';
      const pointer = pointerRef.current;
      const interactionDist = 180;

      particlesRef.current.forEach((p) => {
        // ポインタとの相互作用
        if (pointer.active) {
          const dx = pointer.x - p.x;
          const dy = pointer.y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < interactionDist && dist > 1) {
            const force = (interactionDist - dist) / interactionDist;
            const normalX = dx / dist;
            const normalY = dy / dist;

            if (config.interactionMode === 'attract') {
              p.vx += normalX * force * 0.35 * config.speed;
              p.vy += normalY * force * 0.35 * config.speed;
            } else if (config.interactionMode === 'repel') {
              p.vx -= normalX * force * 0.65 * config.speed;
              p.vy -= normalY * force * 0.65 * config.speed;
            } else if (config.interactionMode === 'vortex') {
              // 渦巻き: 接線方向のベクトル
              p.vx += (-normalY * 0.7 + normalX * 0.2) * force * config.speed;
              p.vy += (normalX * 0.7 + normalY * 0.2) * force * config.speed;
            }
          }
        }

        // 位置の更新と減速摩擦
        p.x += p.vx * config.speed;
        p.y += p.vy * config.speed;
        p.vx *= 0.985;
        p.vy *= 0.985;

        // 壁面の反射
        const margin = 10;
        if (p.x < margin) {
          p.x = margin;
          p.vx *= -1;
        } else if (p.x > width - margin) {
          p.x = width - margin;
          p.vx *= -1;
        }
        if (p.y < margin) {
          p.y = margin;
          p.vy *= -1;
        } else if (p.y > height - margin) {
          p.y = height - margin;
          p.vy *= -1;
        }

        // 微小な自律ゆらぎ
        p.vx += (Math.random() - 0.5) * 0.1;
        p.vy += (Math.random() - 0.5) * 0.1;

        // 描画
        const currentRadius = p.baseRadius * (config.particleSize / 2);
        const glow = currentRadius * 3.5;

        const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, glow);
        grad.addColorStop(0, `hsla(${p.hue}, 100%, 75%, 0.9)`);
        grad.addColorStop(0.4, `hsla(${p.hue}, 90%, 55%, 0.4)`);
        grad.addColorStop(1, `hsla(${p.hue}, 80%, 40%, 0)`);

        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(p.x, p.y, glow, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(p.x, p.y, currentRadius * 0.6, 0, Math.PI * 2);
        ctx.fill();
      });

      // バーストパーティクルの更新と描画
      for (let i = burstsRef.current.length - 1; i >= 0; i--) {
        const bp = burstsRef.current[i];
        bp.x += bp.vx;
        bp.y += bp.vy;
        bp.vx *= 0.94;
        bp.vy *= 0.94;
        bp.life += 1;
        bp.alpha = 1 - bp.life / bp.maxLife;

        if (bp.alpha <= 0) {
          burstsRef.current.splice(i, 1);
          continue;
        }

        const bSize = bp.baseRadius * bp.alpha;
        ctx.fillStyle = `hsla(${bp.hue}, 100%, 70%, ${bp.alpha})`;
        ctx.beginPath();
        ctx.arc(bp.x, bp.y, bSize, 0, Math.PI * 2);
        ctx.fill();
      }

      animFrameIdRef.current = requestAnimationFrame(render);
    };

    animFrameIdRef.current = requestAnimationFrame(render);

    return () => {
      isRunning = false;
      if (animFrameIdRef.current) {
        cancelAnimationFrame(animFrameIdRef.current);
      }
    };
  }, [config]);

  return (
    <div className="particle-app">
      {/* メイン描画キャンバス */}
      <canvas
        ref={canvasRef}
        className="particle-canvas"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerLeave}
      />

      {/* UIオーバーレイレイヤー */}
      <div className="ui-overlay">
        {/* 左上: ステータス情報 */}
        <div className="status-badge">
          <Activity size={14} color="#00f0ff" />
          <span>粒子: {config.count} 基</span>
          <span>•</span>
          <span>モード: {config.interactionMode === 'attract' ? '引力' : config.interactionMode === 'repel' ? '反発' : '渦潮'}</span>
        </div>

        {/* 下部中央: 操作トーストガイド */}
        <div className={showToast ? 'instruction-toast' : 'instruction-toast toast-fade'}>
          画面上をドラッグして粒子を操り、タップで光をバーストさせましょう
        </div>
      </div>

      {/* フローティング設定開閉ボタン */}
      {!isPanelOpen && (
        <button
          type="button"
          className="floating-toggle-btn"
          onClick={() => setIsPanelOpen(true)}
          aria-label="設定を開く"
        >
          <Sliders size={20} />
        </button>
      )}

      {/* 設定パネル */}
      {isPanelOpen && (
        <Controls
          config={config}
          onChangeConfig={handleConfigChange}
          onApplyPreset={handleApplyPreset}
          onBurst={() => triggerBurst()}
          onReset={handleReset}
          onClose={() => setIsPanelOpen(false)}
        />
      )}
    </div>
  );
};

export default App;
